// MNIST inference CLI: ./cli_tool weights.json image.png -> prints predicted digit
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include "lodepng.h"
extern "C" {
#include "cJSON.h"
}

static const double MNIST_MEAN = 0.1307;
static const double MNIST_STD = 0.3081;

struct Layer {
    std::string name;
    int out = 0, in = 0;
    std::vector<double> w; // out x in, row major
    std::vector<double> b;
};

static std::string readFile(const char *path, bool &ok) {
    ok = false;
    FILE *f = fopen(path, "rb");
    if (!f) return std::string();
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (n < 0) { fclose(f); return std::string(); }
    std::string s;
    s.resize((size_t)n);
    size_t rd = fread(&s[0], 1, (size_t)n, f);
    fclose(f);
    s.resize(rd);
    ok = true;
    return s;
}

static bool loadWeights(const char *path, std::vector<Layer> &layers) {
    bool ok = false;
    std::string txt = readFile(path, ok);
    if (!ok) { fprintf(stderr, "cannot read %s\n", path); return false; }
    cJSON *root = cJSON_Parse(txt.c_str());
    if (!root) { fprintf(stderr, "invalid json in %s\n", path); return false; }

    cJSON *sd = root;
    // tolerate wrappers such as {"state_dict": {...}} or {"weights": {...}}
    const char *wrappers[] = {"state_dict", "weights", "model", "params"};
    for (size_t i = 0; i < sizeof(wrappers) / sizeof(wrappers[0]); ++i) {
        cJSON *w = cJSON_GetObjectItemCaseSensitive(root, wrappers[i]);
        if (w && cJSON_IsObject(w)) { sd = w; break; }
    }

    // collect "<prefix>.weight" / "<prefix>.bias" pairs, in file order
    for (cJSON *it = sd->child; it; it = it->next) {
        if (!it->string) continue;
        std::string key(it->string);
        size_t pos = key.rfind(".weight");
        if (pos == std::string::npos || pos + 7 != key.size()) continue;
        if (!cJSON_IsArray(it)) continue;
        Layer L;
        L.name = key.substr(0, pos);
        int rows = cJSON_GetArraySize(it);
        if (rows <= 0) continue;
        cJSON *r0 = cJSON_GetArrayItem(it, 0);
        if (!cJSON_IsArray(r0)) continue;
        int cols = cJSON_GetArraySize(r0);
        L.out = rows; L.in = cols;
        L.w.reserve((size_t)rows * cols);
        for (cJSON *row = it->child; row; row = row->next)
            for (cJSON *v = row->child; v; v = v->next)
                L.w.push_back(cJSON_IsNumber(v) ? v->valuedouble : 0.0);
        if ((int)L.w.size() != rows * cols) { cJSON_Delete(root); fprintf(stderr, "bad weight shape\n"); return false; }
        L.b.assign((size_t)rows, 0.0);
        std::string bkey = L.name + ".bias";
        cJSON *bj = cJSON_GetObjectItemCaseSensitive(sd, bkey.c_str());
        if (bj && cJSON_IsArray(bj)) {
            int i = 0;
            for (cJSON *v = bj->child; v && i < rows; v = v->next, ++i)
                L.b[i] = cJSON_IsNumber(v) ? v->valuedouble : 0.0;
        }
        layers.push_back(L);
    }
    cJSON_Delete(root);
    if (layers.empty()) { fprintf(stderr, "no layers found\n"); return false; }
    return true;
}

static bool loadImage(const char *path, std::vector<double> &pixels /*784, 0..1*/) {
    std::vector<unsigned char> rgba;
    unsigned w = 0, h = 0;
    unsigned err = lodepng::decode(rgba, w, h, path); // RGBA 8-bit
    if (err) { fprintf(stderr, "png decode error %u: %s\n", err, lodepng_error_text(err)); return false; }
    if (w == 0 || h == 0) return false;

    std::vector<double> gray((size_t)w * h);
    for (size_t i = 0; i < (size_t)w * h; ++i) {
        double r = rgba[4 * i + 0], g = rgba[4 * i + 1], b = rgba[4 * i + 2], a = rgba[4 * i + 3];
        double v = 0.299 * r + 0.587 * g + 0.114 * b;
        v = v * (a / 255.0); // composite on black background
        gray[i] = v / 255.0;
    }

    pixels.assign(784, 0.0);
    for (int y = 0; y < 28; ++y) {
        for (int x = 0; x < 28; ++x) {
            unsigned sy = (h == 28) ? (unsigned)y : (unsigned)((y + 0.5) * h / 28.0);
            unsigned sx = (w == 28) ? (unsigned)x : (unsigned)((x + 0.5) * w / 28.0);
            if (sy >= h) sy = h - 1;
            if (sx >= w) sx = w - 1;
            pixels[(size_t)y * 28 + x] = gray[(size_t)sy * w + sx];
        }
    }
    return true;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }
    std::vector<Layer> layers;
    if (!loadWeights(argv[1], layers)) return 1;

    std::vector<double> x;
    if (!loadImage(argv[2], x)) return 1;
    for (size_t i = 0; i < x.size(); ++i) x[i] = (x[i] - MNIST_MEAN) / MNIST_STD;

    for (size_t li = 0; li < layers.size(); ++li) {
        const Layer &L = layers[li];
        if ((int)x.size() != L.in) {
            fprintf(stderr, "dim mismatch at layer %s: got %zu, want %d\n", L.name.c_str(), x.size(), L.in);
            return 1;
        }
        std::vector<double> y((size_t)L.out, 0.0);
        for (int o = 0; o < L.out; ++o) {
            const double *wr = &L.w[(size_t)o * L.in];
            double s = L.b[o];
            for (int i = 0; i < L.in; ++i) s += wr[i] * x[i];
            y[o] = s;
        }
        if (li + 1 < layers.size())
            for (size_t i = 0; i < y.size(); ++i) if (y[i] < 0) y[i] = 0; // ReLU
        x.swap(y);
    }

    int best = 0;
    for (size_t i = 1; i < x.size(); ++i) if (x[i] > x[best]) best = (int)i;
    printf("%d\n", best);
    return 0;
}

